"""Funnel metrics: per-variant step counts, step conversion rates,
and the overall visit-to-purchase rate."""
from __future__ import annotations

import csv
from pathlib import Path

from gen_funnel import STEPS


def load_events(path: str | Path) -> list[dict]:
    with Path(path).open(newline="") as fh:
        return list(csv.DictReader(fh))


def funnel_counts(events: list[dict]) -> dict[str, dict[str, int]]:
    """Count of users reaching each step, per variant.

    Returns {variant: {step: count}} with every step present (0 if unreached),
    ordered along the funnel.
    """
    counts: dict[str, dict[str, int]] = {}
    for ev in events:
        variant = ev["variant"]
        step = ev["step"]
        bucket = counts.setdefault(variant, {s: 0 for s in STEPS})
        bucket[step] += 1
    return counts


def step_conversion_rates(counts: dict[str, int]) -> dict[str, float]:
    """Conditional step-to-next-step conversion rates along the funnel."""
    rates: dict[str, float] = {}
    for i in range(len(STEPS) - 1):
        here, nxt = STEPS[i], STEPS[i + 1]
        denom = counts.get(here, 0)
        rates[f"{here}>{nxt}"] = counts.get(nxt, 0) / denom if denom else 0.0
    return rates


def overall_visit_to_purchase_rate(counts: dict[str, int]) -> float:
    """End-to-end conversion: purchases / visits."""
    visits = counts.get("visit", 0)
    return counts.get("purchase", 0) / visits if visits else 0.0


def summarize(events: list[dict]) -> dict[str, dict]:
    """Full per-variant summary."""
    out: dict[str, dict] = {}
    for variant, counts in sorted(funnel_counts(events).items()):
        out[variant] = {
            "counts": counts,
            "step_rates": step_conversion_rates(counts),
            "overall_rate": overall_visit_to_purchase_rate(counts),
        }
    return out


if __name__ == "__main__":
    import json

    summary = summarize(load_events("events.csv"))
    print(json.dumps(summary, indent=2))

