"""Tests for funnel analysis + significance testing."""
from __future__ import annotations

import csv
import math
from pathlib import Path

import pytest

from gen_funnel import STEPS, simulate, write_events
from funnel import (
    funnel_counts,
    load_events,
    overall_visit_to_purchase_rate,
    step_conversion_rates,
    summarize,
)
from stats import two_proportion_ztest


@pytest.fixture(scope="session")
def events_csv(tmp_path_factory) -> Path:
    """Run the simulation once (seed 42, 20000 users, 50/50 split)."""
    events = simulate(n_users=20000, seed=42)
    return write_events(events, tmp_path_factory.mktemp("data") / "events.csv")


@pytest.fixture(scope="session")
def counts(events_csv) -> dict[str, dict[str, int]]:
    return funnel_counts(load_events(events_csv))


# ---------------------------------------------------------------- fixtures ---

class TestKnownAnswerZTest:
    def test_fixture_200_1000_vs_250_1000(self):
        # Known-answer check. Hand-computed: p_pool = 450/2000 = 0.225,
        # SE = sqrt(0.225*0.775*(1/1000+1/1000)) = sqrt(0.00034875),
        # z = -0.05 / SE = -2.67740.
        z, p = two_proportion_ztest(200, 1000, 250, 1000)
        assert abs(z - (-2.677397763008329)) < 1e-3
        assert 0.0 < p < 0.01

    def test_sign_and_symmetry(self):
        z_pos, _ = two_proportion_ztest(250, 1000, 200, 1000)
        z_neg, _ = two_proportion_ztest(200, 1000, 250, 1000)
        assert z_pos == pytest.approx(-z_neg)


# ------------------------------------------------------------- simulation ----

class TestSimulation:
    def test_split_is_roughly_50_50(self, counts):
        for step in STEPS:
            total = counts["A"][step] + counts["B"][step]
            share_a = counts["A"][step] / total
            assert 0.48 < share_a < 0.52

    def test_counts_monotone_non_increasing(self, counts):
        """Counts must be monotone non-increasing along the funnel, both variants."""
        for variant in ("A", "B"):
            seq = [counts[variant][s] for s in STEPS]
            assert all(a >= b for a, b in zip(seq, seq[1:])), (variant, seq)

    def test_everyone_visits(self, counts):
        assert counts["A"]["visit"] == 10000
        assert counts["B"]["visit"] == 10000

    def test_csv_rows_only_for_reached_steps(self, events_csv):
        reached: dict[str, set[str]] = {}
        with events_csv.open(newline="") as fh:
            rows = list(csv.DictReader(fh))
        for row in rows:
            reached.setdefault(row["user_id"], set()).add(row["step"])
        # No user may have a later-step event without all earlier steps.
        for steps in reached.values():
            idx = sorted(STEPS.index(s) for s in steps)
            assert idx == list(range(len(idx)))


# ------------------------------------------------------- planted A/B effect --

class TestPlantedEffect:
    def test_signup_to_activate_is_significant(self, counts):
        """The planted 0.40 vs 0.46 signup->activate effect: p < 0.01."""
        xA, nA = counts["A"]["activate"], counts["A"]["signup"]
        xB, nB = counts["B"]["activate"], counts["B"]["signup"]
        _, p = two_proportion_ztest(xA, nA, xB, nB)
        assert p < 0.01
        # Direction sanity: B converts better on signup->activate.
        assert xB / nB > xA / nA

    def test_visit_to_signup_not_significant(self, counts):
        """No planted effect on visit->signup (both 0.60): p > 0.05."""
        xA, nA = counts["A"]["signup"], counts["A"]["visit"]
        xB, nB = counts["B"]["signup"], counts["B"]["visit"]
        _, p = two_proportion_ztest(xA, nA, xB, nB)
        assert p > 0.05


# ------------------------------------------------------------ funnel.py ------

class TestFunnelMetrics:
    def test_step_rates_in_unit_interval_and_ordered(self, counts):
        for variant in ("A", "B"):
            rates = step_conversion_rates(counts[variant])
            assert list(rates) == ["visit>signup", "signup>activate", "activate>purchase"]
            for r in rates.values():
                assert 0.0 <= r <= 1.0

    def test_planted_rate_gap_visible_in_metrics(self, counts):
        rates_a = step_conversion_rates(counts["A"])
        rates_b = step_conversion_rates(counts["B"])
        assert rates_b["signup>activate"] - rates_a["signup>activate"] == pytest.approx(0.06, abs=0.03)
        assert rates_b["visit>signup"] == pytest.approx(rates_a["visit>signup"], abs=0.02)

    def test_overall_rate_consistency(self, counts):
        for variant in ("A", "B"):
            overall = overall_visit_to_purchase_rate(counts[variant])
            manual = (
                counts[variant]["purchase"]
                / counts[variant]["visit"]
            )
            assert overall == pytest.approx(manual)
            # Overall rate equals product of conditional step rates.
            prod = math.prod(step_conversion_rates(counts[variant]).values())
            assert overall == pytest.approx(prod, rel=1e-9)

    def test_summarize_shape(self, events_csv):
        summary = summarize(load_events(events_csv))
        assert set(summary) == {"A", "B"}
        for v in ("A", "B"):
            assert set(summary[v]) == {"counts", "step_rates", "overall_rate"}

